const COUNTRIES = ['德国', '日本', '美国', '意大利', '英国', '法国', '瑞典', '韩国', '中国', '捷克', '西班牙'];
const BODIES = ['轿跑', '跑车', '超级跑车', '轿车', '掀背', '敞篷', '旅行车', 'SUV', '皮卡'];
const DRIVES = ['前驱', '后驱', '四驱'];
const ASPS = ['自然吸气', '涡轮增压', '双涡轮', '多涡轮', '机械增压', '机械+涡轮', '电动'];

// 国别"接近"规则：同大区算接近
const REGION = {
  德国: '欧洲', 英国: '欧洲', 意大利: '欧洲', 法国: '欧洲', 瑞典: '欧洲', 捷克: '欧洲', 西班牙: '欧洲',
  日本: '亚洲', 韩国: '亚洲', 中国: '亚洲',
  美国: '北美',
};

// 判定规则：num 类给容差（等价区间），其余要求完全一致
const ATTRS = [
  { key: 'y', label: '年款', short: '年款', type: 'num', tol: 5 },
  { key: 'c', label: '国别', short: '国别', type: 'region' },
  { key: 'cy', label: '气缸', short: '气缸', type: 'num', tol: 2 },
  { key: 'd', label: '车门数', short: '车门', type: 'exact' },
  { key: 'b', label: '车种', short: '车种', type: 'exact' },
  { key: 'dr', label: '驱动', short: '驱动', type: 'exact' },
  { key: 'asp', label: '进气', short: '进气', type: 'exact' },
  { key: 'hp', label: '马力', short: '马力', type: 'num', tol: 50 },
];

// 返回每项的 state(hit/near/miss) 与 dir(1=答案更大更晚, -1=更小更早, 0=相等)
function compare(guess, answer) {
  return ATTRS.map((a) => {
    const g = guess[a.key], t = answer[a.key];
    if (g === t) return { key: a.key, state: 'hit', dir: 0 };
    if (a.type === 'num') {
      const near = Math.abs(g - t) <= a.tol;
      return { key: a.key, state: near ? 'near' : 'miss', dir: t > g ? 1 : -1 };
    }
    if (a.type === 'region') {
      return { key: a.key, state: REGION[g] && REGION[g] === REGION[t] ? 'near' : 'miss', dir: 0 };
    }
    return { key: a.key, state: 'miss', dir: 0 };
  });
}

function normalize(s) {
  return String(s).toLowerCase().replace(/[\s·\-–—_.',()（）&]/g, '');
}

// 检索串：年款 + 英文名 + 中文名 + 车架代号 —— 所以输入 "2003"、"2003 bmw"、"E46" 都能局部检索到
function haystack(c) {
  return normalize(c.y + ' ' + c.n + ' ' + c.zh + ' ' + (c.a || ''));
}

// 按车名 / 中文名 / 车架代号 / 年款 模糊搜索，按命中位置排序
function search(q, limit = 12) {
  const n = normalize(q);
  if (!n) return [];
  const out = CARS.filter((c) => haystack(c).includes(n));
  out.sort((x, y) => (haystack(x).indexOf(n) - haystack(y).indexOf(n)) || x.n.localeCompare(y.n));
  return out.slice(0, limit);
}

// 随机抽一台，避免和上一台重复
function pickRandom(excludeName) {
  let c;
  do { c = CARS[Math.floor(Math.random() * CARS.length)]; }
  while (CARS.length > 1 && c.n === excludeName);
  return c;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { CARS, COUNTRIES, BODIES, DRIVES, ASPS, REGION, ATTRS, compare, search, normalize, pickRandom };
}
